/** Shared dismissed-state for the demo ribbon so the restore control can
 *  live in the app shell (header on desktop, menu on mobile) instead of
 *  floating over content. */
let dismissed = false;
const subs = new Set<() => void>();

export const demoRibbonState = {
  get: (): boolean => dismissed,
  set(value: boolean): void {
    dismissed = value;
    subs.forEach((f) => f());
  },
  sub(f: () => void): () => void {
    subs.add(f);
    return () => subs.delete(f);
  },
};
