/**
 * One-tap hubs that keep the main menu short: More, Admin and My profile.
 * Each lists the screens of its section for the signed-in person.
 */
import React from 'react';
import { Link } from 'react-router-dom';
import { ChevronRight } from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { useAuth } from '@/lib/auth';
import { useFeatures } from '@/lib/features';
import { api } from '@/lib/api';
import { sectionItems, type NavSection } from '@/components/Layout';
import { PageHeader, cardClass } from '@/components/states';
import { navLabel, useI18n, type MessageKey } from '@/i18n';
import type { BoardContextResponse } from '@/pages/BoardContextStrip';

const TITLES: Record<Exclude<NavSection, 'main'>, { title: MessageKey; subtitle: MessageKey }> = {
  more: { title: 'hub.more.title', subtitle: 'hub.more.subtitle' },
  admin: { title: 'hub.admin.title', subtitle: 'hub.admin.subtitle' },
  profile: { title: 'hub.profile.title', subtitle: 'hub.profile.subtitle' },
};


/** Admin hub: four groups plus a "Needs you" strip instead of one long
 *  undifferentiated list. Rare and risky tools sit one level down. */
function AdminHub({ items, t }: { items: ReturnType<typeof sectionItems>; t: (k: MessageKey) => string }): React.JSX.Element {
  const context = useQuery({ queryKey: ['board', 'context'], queryFn: () => api.get<BoardContextResponse>('/api/board/context'), retry: false });
  const backup = useQuery({ queryKey: ['backup-status'], queryFn: () => api.get<{ overdue: boolean }>('/api/admin/backup/status'), retry: false });
  const byTo = new Map(items.map((i) => [i.to, i]));
  const tile = (to: string, label: string, hint?: string): React.JSX.Element | null => {
    const item = byTo.get(to);
    if (!item) return null;
    const Icon = item.icon;
    return (
      <li key={to}>
        <Link to={to} className="flex min-h-[44px] items-center gap-3 rounded-lg px-2 py-2 hover:bg-slate-50 dark:hover:bg-slate-800">
          <Icon className="h-5 w-5 flex-shrink-0 text-[#C80023] dark:text-red-400" />
          <span className="min-w-0 flex-1">
            <span className="block font-medium text-slate-900 dark:text-white">{label}</span>
            {hint ? <span className="block text-sm text-slate-500 dark:text-slate-400">{hint}</span> : null}
          </span>
          <ChevronRight className="h-5 w-5 text-slate-500 dark:text-slate-400" aria-hidden="true" />
        </Link>
      </li>
    );
  };
  const c = context.data;
  const waiting = (c?.applications.submitted ?? 0) + (c?.applications.info_requested ?? 0);
  const needs: Array<{ to: string; text: string }> = [];
  if (waiting > 0) needs.push({ to: '/admin/applications', text: `${waiting} volunteer application${waiting === 1 ? '' : 's'} to review` });
  if ((c?.unreadConversations ?? 0) > 0) needs.push({ to: '/messages', text: `${c!.unreadConversations} unread conversation${c!.unreadConversations === 1 ? '' : 's'}` });
  if (backup.data?.overdue) needs.push({ to: '/admin/backup', text: 'No backup in 7 days' });
  if ((c?.overdueEquipment ?? 0) > 0) needs.push({ to: '/equipment', text: `${c!.overdueEquipment} equipment loan${c!.overdueEquipment === 1 ? '' : 's'} overdue` });
  const group = (title: string, rows: Array<React.JSX.Element | null>): React.JSX.Element | null => {
    const present = rows.filter(Boolean);
    if (present.length === 0) return null;
    return (
      <section className={`${cardClass} p-3`}>
        <h2 className="px-2 pb-1 text-sm font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">{title}</h2>
        <ul className="divide-y divide-slate-100 dark:divide-slate-800">{present}</ul>
      </section>
    );
  };
  void t;
  return (
    <div className="space-y-4">
      {needs.length > 0 ? (
        <section className="rounded-xl border border-amber-300 bg-amber-50 p-3 dark:border-amber-700 dark:bg-amber-950" aria-label="Needs you">
          <h2 className="px-1 pb-1 text-sm font-semibold text-amber-900 dark:text-amber-100">Needs you</h2>
          <ul className="space-y-1">
            {needs.map((n) => (
              <li key={n.to + n.text}>
                <Link to={n.to} className="flex min-h-[44px] items-center justify-between rounded-lg px-2 py-1.5 font-medium text-amber-950 hover:bg-amber-100 dark:text-amber-50 dark:hover:bg-amber-900">
                  {n.text}
                  <ChevronRight className="h-5 w-5" aria-hidden="true" />
                </Link>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
      <div className="grid gap-3 sm:grid-cols-2">
        {group('People', [
          tile('/admin/people', 'People', 'Accounts, roles, invites, how each person is reached'),
          tile('/admin/applications', 'Applications', 'New volunteer sign-ups to review'),
          tile('/admin/departments', 'Departments', 'Coordinators per service, members per group'),
          tile('/admin/cards', 'Volunteer ID cards', 'Private volunteer and vehicle artwork drafts'),
        ])}
        {group('Messages', [
          tile('/admin/announcements', 'Broadcast', 'Message everyone or a group'),
          tile('/admin/templates', 'Message templates', 'Wording of the texts'),
          tile('/admin/notifications', 'Delivery log', 'Every message sent, and whether it arrived'),
        ])}
        {group('Reports', [
          tile('/reports', 'Reports', 'Totals, trends, staffing and equipment'),
          tile('/admin/exports', 'Exports', 'Download data'),
        ])}
        <details className={`${cardClass} p-3`}>
          <summary className="min-h-[44px] cursor-pointer px-2 py-2 text-sm font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">System</summary>
          <ul className="divide-y divide-slate-100 dark:divide-slate-800">
            {tile('/admin/settings', 'Settings', 'Dispatch, messages and feature switches')}
            {tile('/admin/backup', 'Backup', 'Encrypted full database download')}
            {tile('/admin/audit', 'Audit log', 'Who changed what')}
            {tile('/admin/data-fixes', 'Data fixes', 'Correct how a ride ended; tidy up accounts')}
          </ul>
        </details>
      </div>
    </div>
  );
}

export function HubPage({ section }: { section: Exclude<NavSection, 'main'> }): React.JSX.Element {
  const { user } = useAuth();
  const features = useFeatures(Boolean(user));
  const role = user?.role ?? 'volunteer';
  const items = sectionItems(role, user?.navHidden, section, features);
  const { t } = useI18n();
  const title = t(TITLES[section].title);
  const subtitle = t(TITLES[section].subtitle);
  if (section === 'admin') {
    return (
      <div className="space-y-4">
        <PageHeader title={title} subtitle={subtitle} />
        <AdminHub items={[...items, ...sectionItems(role, user?.navHidden, 'more', features)]} t={t} />
      </div>
    );
  }
  return (
    <div className="space-y-4">
      <PageHeader title={title} subtitle={subtitle} />
      <ul className="space-y-2">
        {items.map((item) => {
          const Icon = item.icon;
          return (
            <li key={item.to}>
              <Link
                to={item.to}
                className={`${cardClass} flex min-h-[56px] items-center gap-3 p-4 hover:bg-slate-50 dark:hover:bg-slate-800`}
              >
                <Icon className="h-5 w-5 flex-shrink-0 text-[#C80023] dark:text-red-400" />
                <span className="min-w-0 flex-1">
                  <span className="block font-medium text-slate-900 dark:text-white">{navLabel(t, item.to, item.label)}</span>
                  {item.hint ? (
                    <span className="block text-sm text-slate-500 dark:text-slate-400">{item.hint}</span>
                  ) : null}
                </span>
                <ChevronRight className="h-5 w-5 text-slate-500 dark:text-slate-400" aria-hidden="true" />
              </Link>
            </li>
          );
        })}
      </ul>
      {section === 'more' ? (
        <p className="pt-2 text-center text-sm text-slate-500 dark:text-slate-400">
          <Link to="/privacy" className="underline">Privacy notice</Link>
        </p>
      ) : null}
    </div>
  );
}
