/**
 * Accept from the link in an SMS or push notification: /o/<code>.
 *
 * A plain GET navigation must never accept the ride: chat apps and SMS
 * clients fetch link previews, and a preview fetch used to claim the trip
 * before the volunteer ever saw it. The page therefore shows one explicit
 * "Accept this ride" tap. That is one tap from the lock screen, same as
 * before; the difference is that the tap, not the page load, accepts.
 *
 * If they are not signed in, <RequireAuth> sends them to /login carrying this
 * path, and they land back here the moment they are in.
 */
import React from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { CheckCircle2, XCircle } from 'lucide-react';
import { ApiError, api, errorMessage } from '@/lib/api';
import { invalidateTrips } from '@/lib/query';
import { FullPageSpinner } from '@/lib/auth';
import { primaryButtonClass, secondaryButtonClass } from '@/components/states';
import type { AcceptOfferResponse } from '@/types/api';

export function AcceptFromLinkPage(): React.JSX.Element {
  const { code = '' } = useParams<{ code: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const accept = useMutation({
    mutationFn: () => api.post<AcceptOfferResponse>('/api/offers/accept', { code }),
    onError: (error: unknown) => {
      if (error instanceof ApiError && error.isConflict) return; // shown in place below
      toast.error(errorMessage(error));
    },
    onSuccess: (data) => {
      invalidateTrips(queryClient, data.tripId);
      toast.success(`Ride ${data.reference} is yours.`);
      navigate(`/trips/${data.tripId}`, { replace: true });
    },
  });

  if (accept.isIdle) {
    return (
      <div className="mx-auto max-w-md rounded-xl border border-slate-200 bg-white p-6 text-center dark:border-slate-700 dark:bg-slate-900">
        <CheckCircle2 className="mx-auto h-10 w-10 text-[#C80023] dark:text-red-400" aria-hidden="true" />
        <h1 className="mt-3 text-lg font-semibold text-slate-900 dark:text-white">Take this ride?</h1>
        <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
          Tap accept and it is yours — dispatch and the caller are told right away.
        </p>
        <button type="button" className={`${primaryButtonClass} mt-5 w-full`} onClick={() => accept.mutate()}>
          Accept this ride
        </button>
        <Link to="/my-trips" className={`${secondaryButtonClass} mt-2 w-full`}>
          Not now
        </Link>
      </div>
    );
  }

  if (accept.isPending) return <FullPageSpinner label="Accepting this ride" />;

  if (accept.isError) {
    const err = accept.error;
    const notYours = err instanceof ApiError && err.code === 'not_your_offer';
    const conflict = err instanceof ApiError && err.isConflict && !notYours;
    return (
      <div className="mx-auto max-w-md rounded-xl border border-slate-200 bg-white p-6 text-center dark:border-slate-700 dark:bg-slate-900">
        <XCircle className="mx-auto h-10 w-10 text-[#C80023] dark:text-red-400" aria-hidden="true" />
        <h1 className="mt-3 text-lg font-semibold text-slate-900 dark:text-white">
          {notYours
            ? 'This offer was sent to a different volunteer'
            : conflict
              ? 'Another volunteer accepted this first'
              : 'We could not accept this ride'}
        </h1>
        <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
          {notYours
            ? 'Your own open offers are listed under My rides.'
            : conflict
              ? 'Nothing went wrong on your side — the ride is covered. Thank you for answering.'
              : errorMessage(err)}
        </p>
        <div className="mt-5 flex flex-col gap-2 sm:flex-row sm:justify-center">
          <Link to="/my-trips" className={primaryButtonClass}>
            See open offers
          </Link>
          {conflict ? null : (
            <button type="button" className={secondaryButtonClass} onClick={() => accept.mutate()}>
              Try again
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-md rounded-xl border border-slate-200 bg-white p-6 text-center dark:border-slate-700 dark:bg-slate-900">
      <CheckCircle2 className="mx-auto h-10 w-10 text-green-600" aria-hidden="true" />
      <h1 className="mt-3 text-lg font-semibold text-slate-900 dark:text-white">This ride is yours</h1>
      <Link to="/my-trips" className={`${primaryButtonClass} mt-4`}>
        Open the details
      </Link>
    </div>
  );
}
